def accept_dispatch(request, queue):
    identity = request.headers['Idempotency-Key']
    job = queue.publish_once(identity, request.body)
    # RFC 9110: 202 only acknowledges acceptance, never completion.
    return {'status': 202, 'location': f'/dispatch/{job}'}

