func receiveBatch(input []Span, clock Clock, sink Sink) error {
    // 缺失 traceparent 不拒收，落 span 时保留原始接收时间。
    for _, span := range input {
        sink.Enqueue(span.WithReceivedAt(clock.Now()))
    }
    return nil
}

