export async function saveDraft(db, draft) {
  // 同一事务内写入草稿与待同步任务，避免只落盘一半。
  await db.transaction(['drafts', 'outbox'], async tx => {
    await tx.drafts.put(draft)
    await tx.outbox.put({id: draft.id})
  })
}

workspace.src/drafts/sync.ts:
export async function flushOutbox(db, remote) {
  for (const job of await db.outbox.pending()) {
    const receipt = await remote.upload(job.id)
    if (receipt.ok) await db.outbox.remove(job.id)
  }
}

